/// <summary>
///     Data Controller class for <c>AVABOSProvisionReportController</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVABOSProvisionReport</c> SSRS Report.
/// </remarks>
internal final class AVABOSProvisionReportController extends  SrsReportRunController
{
    Args            clsArgs;
    KCS_BOSTrans_C  clsKCS_BOSTrans_C;
    KCS_TOSTable    clsKCS_TOSTable;
    CustTable       clsCustTable;
    CustTable       clsRecipientACCustTable;
    boolean         clsPreviewMode;

}

Method.Source:
/// <summary>
///     AVA <c>construct</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <returns>
///     <c>AVABOSProvisionReportController</c> as return value
/// </returns>
public static AVABOSProvisionReportController construct()
{
    return new AVABOSProvisionReportController();
}

/// <summary>
///     AVA <c>parmArgs</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_parmValue">
///     <c>RefRecId</c> as type
/// </param>
/// <returns>
///     <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///     AVA <c>parmKCS_BOSTrans_C</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_parmValue">
///     <c>SalesTable</c> as type
/// </param>
/// <returns>
///     <c>KCS_BOSTrans_C</c> as return value
/// </returns>
public KCS_BOSTrans_C parmKCS_BOSTrans_C(KCS_BOSTrans_C _parmValue = clsKCS_BOSTrans_C)
{
    clsKCS_BOSTrans_C = _parmValue;

    return clsKCS_BOSTrans_C;
}

 /// <summary>
 ///     AVA <c>parmRecipientACCustTable</c> method.
 ///     AVA - Schneider 10.04.2024
/// </summary>
 /// <param name="_parmValue">
 ///    <c>CustTable</c> as type
 /// </param>
 /// <returns>
 ///    <c>CustTable</c> as return value
