     clsRecipientACCustTable = _parmValue;

     return clsRecipientACCustTable;
 }

/// <summary>
///     AVA <c>parmCustTable</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_parmValue">
///     <c>CustTable</c> as type
/// </param>
/// <returns>
///     <c>CustTable</c> as return value
/// </returns>
public CustTable parmCustTable(CustTable _parmValue = clsCustTable)
{
    clsCustTable = _parmValue;

    return clsCustTable;
}

/// <summary>
///     AVA <c>main</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABOSProvisionReportController controller;

    controller = AVABOSProvisionReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVABOSProvisionReport, Report));
    controller.parmDialogCaption("@NDX:NXAProvisionReport");
    controller.startOperation();
}

/// <summary>
///     AVA <c>prePromptModifyContract</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
protected void prePromptModifyContract()
{
    AVABOSProvisionReportContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();

    contract.parmCustAccount(clsCustTable.AccountNum);
    contract.parmRecipientAC(clsRecipientACCustTable.AccountNum);
    contract.parmPrintMode(AVASumInvoicePositions::Positions);

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        /*
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVABOSProvisionReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else 
        */   
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVABOSProvisionReportAction))
        {
            clsPreviewMode = false;
        }
        /*
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVABOSProvisionReportOutput))
        {
            clsPreviewMode = false;
        }
        */
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
///     AVA - Schneider 10.04.2024
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVABOSProvisionReportController</c> as return value
/// </returns>
public static AVABOSProvisionReportController newFromArgs(Args _args)
{
    AVABOSProvisionReportController locController;
    Common                          locCommon;
    KCS_BOSTrans_C                  locKCS_BOSTrans_C;
    CustTable                       locCustTable;
    CustTable                       locRecipientACCustTable;

    //locController = new AVABOSProvisionReportController();
    locController = AVABOSProvisionReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();

            switch(locCommon.TableId)
            {
                case tableNum(KCS_BOSTrans_C):
                    locKCS_BOSTrans_C = locCommon;
                    locController.parmKCS_BOSTrans_C(locKCS_BOSTrans_C);
                    if(locKCS_BOSTrans_C.RecipientAC)
                    {
                        locRecipientACCustTable = CustTable::find(locKCS_BOSTrans_C.RecipientAC);
                        locController.parmCustTable(locCustTable);
                    }
                    if(locKCS_BOSTrans_C.RecipientAC)
                    {
                        locCustTable            = CustTable::find(locKCS_BOSTrans_C.CustAccount);
                        locController.parmRecipientACCustTable(locCustTable);
                    }
                    break;

                case tableNum(CustTable):
                    locCustTable = locCommon;
                    locController.parmCustTable(locCustTable);
                    break;

                default:
                    locController.parmLoadFromSysLastValue(true);
            }
        }
        else
        {
            locController.parmLoadFromSysLastValue(true);
        }
    }
    return locController;
}
